def app(id, ok, result, note=None, set_=None):
    op = {"op": "upsert", "collection": "items", "id": id, "append": {"checks": [{"ok": ok, "src": SRC, "result": result, "when": W}]}}
    if note: op["append"]["notes"] = [{"who": "Claude", "text": note, "at": NOW}]
    if set_: op["set"] = set_
    ops.append(op)
def newrow(id, patient, dob, facility, amdid, need, why, amount, status, note, carrier=""):
    ops.append({"op": "upsert", "collection": "items", "id": id, "set": {"patient": patient, "dob": dob, "facility": facility, "amdid": amdid, "mbi": "", "need": need, "why": why, "amount": amount, "status": status, "inscarrier": carrier, "created": NOW, "updated": NOW}, "append": {"notes": [{"who": "Claude", "text": note, "at": NOW}], "checks": [{"ok": "human" if status == "william" else "ok", "src": SRC, "result": need[:300], "when": W}]}})
